<section class="dashboard-hero"><span class="hero-icon"><i class="bi bi-heart-pulse"></i></span><div><p class="section-label">MUTALA & DIKAPA</p><h2>Gestion des élevages</h2><p>Animaux vivants en têtes, productions et conversions pesées strictement séparées.</p></div></section><?php if($success):?><div class="app-alert app-alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="app-alert app-alert-error"><?=e($error)?></div><?php endif;?>
<div class="dashboard-grid dashboard-grid-2"><section class="form-panel"><h3>Bâtiment ou étang</h3><form method="post" action="<?=e(base_url('livestock/facilities'))?>" class="enterprise-form"><?=csrf_field()?><input name="code" placeholder="Code" required><input name="name" placeholder="Nom" required><select name="facility_type"><option value="housing">Bâtiment élevage</option><option value="poultry_house">Poulailler</option><option value="pond">Étang</option></select><input type="number" step="0.001" name="area_m2" placeholder="Surface m² (étang)"><input type="number" name="capacity_heads" placeholder="Capacité têtes"><button>Créer</button></form></section><section class="form-panel"><h3>Nouveau lot vivant</h3><form method="post" action="<?=e(base_url('livestock/batches'))?>" class="enterprise-form"><?=csrf_field()?><select name="species_id"><?php foreach($refs['species'] as$x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><select name="facility_id"><?php foreach($refs['facilities'] as$x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><select name="purpose"><option value="meat">Chair</option><option value="laying">Ponte</option><option value="fattening">Engraissement</option><option value="breeding">Reproduction</option></select><input type="date" name="started_at" required><input type="number" name="initial_heads" placeholder="Effectif initial" required><input type="number" step="0.001" name="initial_average_weight_kg" placeholder="Poids moyen initial kg"><input type="number" step="0.001" name="initial_total_weight_kg" placeholder="Poids initial poissons kg"><button>Créer lot</button></form></section></div>
<section class="table-panel"><h3>Lots d’élevage</h3><table class="enterprise-table"><thead><tr><th>Lot</th><th>Espèce</th><th>Unité</th><th>Vivant</th><th>Poids moyen</th><th>Aliment</th><th>Œufs</th></tr></thead><tbody><?php foreach($batches as$b):?><tr><td><?=e($b['batch_number'])?></td><td><?=e($b['species_name'].' / '.$b['purpose'])?></td><td><?=e($b['facility_name'])?></td><td><strong><?=e($b['current_heads'])?> têtes</strong></td><td><?=e($b['current_average_weight_kg']?:'-')?> kg</td><td><?=e($b['feed_kg'])?> kg</td><td><?=e($b['eggs_count'])?> unités</td></tr><?php endforeach;?></tbody></table></section>
<div class="dashboard-grid dashboard-grid-2"><section class="form-panel"><h3>Alimentation et pesée</h3><form method="post" action="<?=e(base_url('livestock/feedings'))?>" class="enterprise-form"><?=csrf_field()?><select name="batch_id"><?php foreach($batches as$b):?><option value="<?=$b['id']?>"><?=e($b['batch_number'])?></option><?php endforeach;?></select><select name="feed_product_id"><option value="">Aliment externe</option><?php foreach($refs['feed_products'] as$x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><input type="number" step="0.001" name="quantity_kg" placeholder="Aliment kg"><input type="datetime-local" name="fed_at" required><input type="number" step="0.0001" name="unit_cost" placeholder="Coût/kg"><button>Alimenter</button></form><form method="post" action="<?=e(base_url('livestock/weighings'))?>" class="enterprise-form"><?=csrf_field()?><select name="batch_id"><?php foreach($batches as$b):?><option value="<?=$b['id']?>"><?=e($b['batch_number'])?></option><?php endforeach;?></select><input type="number" name="sample_heads" placeholder="Têtes pesées"><input type="number" step="0.001" name="total_weight_kg" placeholder="Poids total kg"><input type="datetime-local" name="weighed_at" required><button>Enregistrer pesée</button></form></section><section class="form-panel"><h3>Production avicole</h3><form method="post" action="<?=e(base_url('livestock/poultry'))?>" class="enterprise-form"><?=csrf_field()?><select name="batch_id"><?php foreach($batches as$b):if($b['category']!=='poultry')continue;?><option value="<?=$b['id']?>"><?=e($b['batch_number'])?></option><?php endforeach;?></select><input type="date" name="production_date" required><input type="number" name="eggs_count" placeholder="Œufs produits"><input type="number" name="mortality_heads" placeholder="Mortalité têtes"><input type="number" name="sold_heads" placeholder="Vente têtes"><button>Enregistrer</button></form></section></div>
<section class="form-panel"><h3>Conversion formelle : abattage, pêche ou pesée</h3><p>Cette opération est le seul passage autorisé des têtes vivantes vers un stock en kilogrammes.</p><form method="post" action="<?=e(base_url('livestock/conversions'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><select name="batch_id"><?php foreach($batches as$b):?><option value="<?=$b['id']?>"><?=e($b['batch_number'].' — '.$b['current_heads'].' têtes')?></option><?php endforeach;?></select><select name="conversion_type"><option value="slaughter">Abattage</option><option value="fish_catch">Pêche</option><option value="formal_weighing">Pesée de conversion</option></select><input type="number" name="input_heads" placeholder="Têtes converties"><input type="number" step="0.001" name="gross_weight_kg" placeholder="Poids brut kg"><input type="number" step="0.001" name="tare_weight_kg" placeholder="Tare kg"><input type="datetime-local" name="converted_at" required></div><button class="btn-primary">Soumettre conversion</button></form><table class="enterprise-table"><tbody><?php foreach($conversions as$c):?><tr><td><?=e($c['conversion_number'])?></td><td><?=e($c['batch_number'])?></td><td><?=e($c['input_heads'])?> têtes → <?=e($c['net_weight_kg'])?> kg</td><td><?=e($c['status'])?></td><td><?php if($c['status']==='submitted'):?><form method="post" action="<?=e(base_url('livestock/conversions/'.$c['id'].'/validate'))?>"><?=csrf_field()?><button>Valider conversion</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<section class="form-panel"><h3>BTR vers la boucherie</h3><form method="post" action="<?=e(base_url('livestock/transfers'))?>" class="enterprise-form"><?=csrf_field()?><div class="form-grid"><select name="batch_id"><?php foreach($batches as$b):?><option value="<?=$b['id']?>"><?=e($b['batch_number'])?></option><?php endforeach;?></select><select name="source_unit"><option value="head">Animaux vivants — têtes</option><option value="kg">Stock converti/pesé — kg</option></select><input type="number" name="quantity_heads" placeholder="Nombre de têtes"><select name="weight_stock_id"><option value="">Stock pesé</option><?php foreach($conversions as$c):if(empty($c['stock_id']))continue;?><option value="<?=$c['stock_id']?>"><?=e($c['batch_number'].' — '.$c['quantity_kg'].' kg')?></option><?php endforeach;?></select><input type="number" step="0.001" name="quantity_kg" placeholder="Quantité kg"><input name="truck_plate" placeholder="Plaque"><input name="driver_name" placeholder="Chauffeur"></div><button class="btn-primary">Créer BTR</button></form><table class="enterprise-table"><tbody><?php foreach($transfers as$t):?><tr><td><?=e($t['document_number']?:$t['transfer_number'])?></td><td><?=e($t['batch_number'])?></td><td><?=e($t['source_unit']==='head'?$t['quantity_heads'].' têtes':$t['quantity_kg'].' kg')?></td><td><?=e($t['status'])?></td><td><?php if($t['status']==='draft'):?><form method="post" action="<?=e(base_url('livestock/transfers/'.$t['id'].'/approve'))?>"><?=csrf_field()?><button>Valider</button></form><?php elseif($t['status']==='approved'):?><form method="post" action="<?=e(base_url('livestock/transfers/'.$t['id'].'/dispatch'))?>"><?=csrf_field()?><button>Expédier</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
